-- 班次调整申请明细项: 按field_code承载：after_snapshot、before_snapshot、handover_items
CREATE TABLE IF NOT EXISTS attendance.shift_change_request_item (
    id uuid DEFAULT gen_random_uuid() NOT NULL PRIMARY KEY,
    tenant_id uuid NOT NULL,
    created_by uuid,
    created_at timestamptz DEFAULT now() NOT NULL,
    updated_by uuid,
    updated_at timestamptz DEFAULT now() NOT NULL,
    is_deleted boolean DEFAULT false NOT NULL,
    deleted_at timestamptz,
    master_id uuid NOT NULL,
    field_code varchar(128) NOT NULL,
    item_seq integer DEFAULT 0 NOT NULL,
    item_key varchar(128),
    item_name varchar(255),
    item_value_text text,
    item_value_number numeric(24,8),
    item_value_json jsonb,
    related_object_type varchar(128),
    related_object_id uuid,
    amount numeric(18,2),
    quantity numeric(18,6),
    sort_no integer DEFAULT 0 NOT NULL
);
COMMENT ON TABLE attendance.shift_change_request_item IS '班次调整申请明细项｜按field_code承载：after_snapshot、before_snapshot、handover_items';
COMMENT ON COLUMN attendance.shift_change_request_item.id IS '主键ID｜敏感级别:P1-内部';
COMMENT ON COLUMN attendance.shift_change_request_item.tenant_id IS '租户ID｜敏感级别:P1-内部｜规则:所有业务唯一键必须包含tenant_id';
COMMENT ON COLUMN attendance.shift_change_request_item.created_by IS '创建人｜敏感级别:P1-内部';
COMMENT ON COLUMN attendance.shift_change_request_item.created_at IS '创建时间｜敏感级别:P1-内部';
COMMENT ON COLUMN attendance.shift_change_request_item.updated_by IS '更新人｜敏感级别:P1-内部';
COMMENT ON COLUMN attendance.shift_change_request_item.updated_at IS '更新时间｜敏感级别:P1-内部';
COMMENT ON COLUMN attendance.shift_change_request_item.is_deleted IS '逻辑删除｜敏感级别:P1-内部';
COMMENT ON COLUMN attendance.shift_change_request_item.deleted_at IS '删除时间｜敏感级别:P1-内部';
COMMENT ON COLUMN attendance.shift_change_request_item.master_id IS '主表ID｜敏感级别:P1-内部';
COMMENT ON COLUMN attendance.shift_change_request_item.field_code IS '来源字段编码｜敏感级别:P1-内部';
COMMENT ON COLUMN attendance.shift_change_request_item.item_seq IS '明细序号｜敏感级别:P1-内部';
COMMENT ON COLUMN attendance.shift_change_request_item.item_key IS '明细键｜敏感级别:P1-内部';
COMMENT ON COLUMN attendance.shift_change_request_item.item_name IS '明细名称｜敏感级别:P1-内部';
COMMENT ON COLUMN attendance.shift_change_request_item.item_value_text IS '文本值｜敏感级别:P1-内部';
COMMENT ON COLUMN attendance.shift_change_request_item.item_value_number IS '数值｜敏感级别:P1-内部';
COMMENT ON COLUMN attendance.shift_change_request_item.item_value_json IS '结构化值｜敏感级别:P1-内部';
COMMENT ON COLUMN attendance.shift_change_request_item.related_object_type IS '关联对象类型｜敏感级别:P1-内部';
COMMENT ON COLUMN attendance.shift_change_request_item.related_object_id IS '关联对象ID｜敏感级别:P1-内部';
COMMENT ON COLUMN attendance.shift_change_request_item.amount IS '金额｜敏感级别:P1-内部';
COMMENT ON COLUMN attendance.shift_change_request_item.quantity IS '数量｜敏感级别:P1-内部';
COMMENT ON COLUMN attendance.shift_change_request_item.sort_no IS '排序｜敏感级别:P1-内部';
